const DATASET_VERSION = "2.0_500_CSV";

function initAppStorage() {
  const currentVer = localStorage.getItem("cms_dataset_version");
  const stored = localStorage.getItem("cms_tickets");
  
  if (!stored || currentVer !== DATASET_VERSION) {
    let userTickets = [];
    if (stored) {
      try {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) {
          // Preserve any real grievances filed by citizen in portal
          userTickets = parsed.filter(t => t.ticket_id && t.ticket_id.startsWith("CMP-") && parseInt(t.ticket_id.slice(4)) >= 10000 && t.ticket_id !== "CMP-10025");
        }
      } catch (e) {}
    }
    const merged = [...userTickets, ...MASTER_DATASET];
    localStorage.setItem("cms_tickets", JSON.stringify(merged));
    localStorage.setItem("cms_dataset_version", DATASET_VERSION);
  }
}
initAppStorage();

function getCurrentUser() {
  try {
    const raw = localStorage.getItem("cms_current_user");
    if (raw) {
      const u = JSON.parse(raw);
      if (u && typeof u === "object" && u.email) return u;
    }
  } catch (e) {}
  return null;
}

function getTickets() {
  try {
    const raw = localStorage.getItem("cms_tickets");
    if (raw) {
      const t = JSON.parse(raw);
      if (Array.isArray(t) && t.length > 0) return t;
    }
  } catch (e) {}
  return MASTER_DATASET;
}

function saveTickets(tickets) {
  try {
    localStorage.setItem("cms_tickets", JSON.stringify(tickets));
  } catch (e) {
    console.error("Save tickets error", e);
  }
}

function getNotifications(userEmail) {
  try {
    const raw = localStorage.getItem("cms_notifications");
    if (raw) {
      const notifs = JSON.parse(raw);
      if (Array.isArray(notifs)) {
        if (!userEmail) return notifs;
        return notifs.filter(n => (n.user_email || "").toLowerCase() === userEmail.toLowerCase());
      }
    }
  } catch (e) {}
  return [];
}

function addNotification(userEmail, title, message) {
  try {
    const notifs = getNotifications();
    notifs.unshift({
      id: Date.now(),
      user_email: userEmail || "user@demo.com",
      title: title,
      message: message,
      time: getLocalTimestamp(), // Local real-time
      read: false
    });
    localStorage.setItem("cms_notifications", JSON.stringify(notifs));
  } catch (e) {
    console.error("Notification error", e);
  }
}

function logout() {
  localStorage.removeItem("cms_current_user");
  window.location.href = "login.html";
}

// AI Complaint Classifier & Auto-Routing Engine
function predictComplaintAI(text) {
  const low = (text || "").toLowerCase().trim();
  if (!low) {
    return {
      category: "General",
      priority: "Medium",
      team: "General Support Team"
    };
  }

  let category = "General";
  let priority = "Medium";
  let team = "General Support Team";

  // Category Detection
  const isTechnical = /\b(internet|wifi|wi-fi|broadband|network|connection|down|slow|speed|outage|router|modem|server|error|bug|crash|glitch|loading|website|500|404|technical|disconnect|disconnection|latency|ping)\b/i.test(low);
  const isBilling = /\b(bill|billing|charge|charged|payment|deduct|deducted|refund|money|amount|invoice|transaction|paid|receipt|debit|bank|upi|wallet|overcharge|kat gaya|paisa)\b/i.test(low);
  const isDelivery = /\b(delivery|order|courier|shipment|shipped|shipping|tracking|dispatch|dispatched|package|parcel|damaged|delayed|undelivered|item|product)\b/i.test(low);
  const isAccount = /\b(hack|hacked|compromised|stolen|fraud|scam|password|login|otp|2fa|verification|security|unauthorized|blocked|suspended)\b/i.test(low);
  const isService = /\b(plan|upgrade|subscription|sim|activation|activate|service|agent|support|representative|staff|rude|customer care|response|cancel|cancellation)\b/i.test(low);

  if (isBilling) {
    category = "Billing";
    team = "Billing & Finance Support";
  } else if (isTechnical) {
    category = "Technical";
    team = "Technical Support Team";
  } else if (isDelivery) {
    category = "Delivery";
    team = "Logistics & Delivery Support";
  } else if (isAccount) {
    category = "Account";
    team = "Account Security Team";
  } else if (isService) {
    category = "Service";
    team = "Customer Relations Team";
  }

  // Priority Detection
  const isUrgent = /\b(urgent|urgently|emergency|critical|immediately|asap|stolen|fraud|scam|severe|worst|danger|hacked|disaster|loss)\b/i.test(low);
  const isHigh = /\b(frustrated|fail|failed|failure|down|deduct|deducted|refund|money|crash|broken|not working|unable|stuck|error|cheat|illegal|unauthorized)\b/i.test(low);
  const isLow = /\b(inquiry|question|query|suggestion|feedback|info|information|clarification|how to)\b/i.test(low);

  if (isUrgent) {
    priority = "Urgent";
  } else if (isHigh) {
    priority = "High";
  } else if (isLow) {
    priority = "Low";
  }

  return { category, priority, team };
}

